-- Frameworks
INSERT INTO frameworks (code, name, description) VALUES ('ISO45001', 'ISO 45001', 'The international standard for occupational health and safety management systems. It helps you prevent work-related injury and ill health and keep improving safety performance.')
  ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO frameworks (code, name, description) VALUES ('ISO27001', 'ISO 27001', 'The international standard for information security management systems (ISMS). It helps you protect the confidentiality, integrity and availability of information using a risk-based set of controls.')
  ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO frameworks (code, name, description) VALUES ('UAE_PDPL', 'UAE PDPL', 'UAE Federal Decree-Law No. 45 of 2021 on the Protection of Personal Data. It sets the rules for collecting, using, sharing and protecting personal data in the UAE.')
  ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO frameworks (code, name, description) VALUES ('OSHAD', 'Abu Dhabi OSHAD', 'The Abu Dhabi Occupational Safety and Health System Framework (OSHAD-SF). It is mandatory for many entities in Abu Dhabi and sets out the elements, mechanisms and codes of practice for managing workplace safety.')
  ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO frameworks (code, name, description) VALUES ('GDPR', 'GDPR', 'The EU General Data Protection Regulation (2016/679). It applies when you process personal data of people in the EU, and covers lawful processing, individual rights and breach notification.')
  ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO frameworks (code, name, description) VALUES ('BEST_PRACTICE', 'General Best Practice', 'A plain-language, framework-neutral approach based on widely recognised good practice. A sensible starting point when no specific standard or regulation applies.')
  ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

-- Policy templates
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Health & Safety', id, '[{"title":"Purpose","body":"{{company_name}} is committed to providing safe and healthy working conditions for everyone affected by its {{industry}} activities, and to preventing work-related injury and ill health.\nThis policy forms part of {{company_name}}''s occupational health and safety (OH&S) management system and is aligned with ISO 45001:2018, Clause 5.2 (OH&S policy)."},{"title":"Scope","body":"This policy applies to all {{employee_count}} employees of {{company_name}}, as well as contractors, subcontractors, visitors and anyone else working at or visiting sites under {{company_name}}''s control in {{location}}."},{"title":"Definitions","body":"• Hazard: anything with the potential to cause harm.\n• Risk: the combination of the likelihood of harm and its severity.\n• Near miss: an event that could have caused injury or damage but did not.\n• PPE: personal protective equipment, such as safety footwear, gloves, eye and hearing protection."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• HSE Manager: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"To achieve its commitment, {{company_name}} will:\n• Identify hazards and assess risks before work begins, and review assessments when work changes.\n• Apply the hierarchy of controls: eliminate, substitute, engineer, administrate, then protect with PPE.\n• Provide safe plant, equipment and systems of work, and suitable PPE at no cost to workers.\n• Give every worker the right to stop work they reasonably believe to be unsafe, without fear of reprisal.\n• Monitor workplace conditions through inspections, audits and health surveillance where required.\n• Consult and involve non-managerial workers in hazard identification, risk assessment and decisions on controls (ISO 45001 Clause 5.4).\n• Identify legal and other requirements that apply and evaluate compliance with them at planned intervals (Clauses 6.1.3 and 9.1.2).\n• Set measurable OH&S objectives and plan how they will be achieved (Clause 6.2)."},{"title":"Training","body":"• All new starters complete health and safety induction before starting work.\n• Task-specific training (for example, working at height, manual handling or forklift operation) is given before workers carry out those tasks.\n• Refresher training is completed at least annually, and training records are kept."},{"title":"Reporting","body":"• All incidents, near misses and unsafe conditions must be reported to a supervisor immediately and logged within 24 hours.\n• Workers can raise safety concerns with their manager, a safety representative or the HSE Manager at any time.\n• Incidents and nonconformities are investigated, root causes identified and corrective actions tracked to closure (Clause 10.2)."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\nPerformance against this policy is considered in management review (Clause 9.3) and used to drive continual improvement (Clause 10.3).\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'ISO45001'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Health & Safety', id, '[{"title":"Purpose","body":"{{company_name}} is committed to providing safe and healthy working conditions for everyone affected by its {{industry}} activities, and to preventing work-related injury and ill health.\nThis policy is aligned with the Abu Dhabi Occupational Safety and Health System Framework (OSHAD-SF), including Element 1 (Roles, Responsibilities and Self-Regulation)."},{"title":"Scope","body":"This policy applies to all {{employee_count}} employees of {{company_name}}, as well as contractors, subcontractors, visitors and anyone else working at or visiting sites under {{company_name}}''s control in {{location}}."},{"title":"Definitions","body":"• Hazard: anything with the potential to cause harm.\n• Risk: the combination of the likelihood of harm and its severity.\n• Near miss: an event that could have caused injury or damage but did not.\n• PPE: personal protective equipment, such as safety footwear, gloves, eye and hearing protection."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• HSE Manager: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"To achieve its commitment, {{company_name}} will:\n• Identify hazards and assess risks before work begins, and review assessments when work changes.\n• Apply the hierarchy of controls: eliminate, substitute, engineer, administrate, then protect with PPE.\n• Provide safe plant, equipment and systems of work, and suitable PPE at no cost to workers.\n• Give every worker the right to stop work they reasonably believe to be unsafe, without fear of reprisal.\n• Monitor workplace conditions through inspections, audits and health surveillance where required.\n• Maintain an OSH management system proportionate to {{company_name}}''s risk rating, as required by OSHAD-SF.\n• Apply the OSHAD-SF Codes of Practice that are relevant to the hazards present in {{industry}} operations.\n• Keep OSH records and documentation available for inspection by the relevant Sector Regulatory Authority."},{"title":"Training","body":"• All new starters complete health and safety induction before starting work.\n• Task-specific training (for example, working at height, manual handling or forklift operation) is given before workers carry out those tasks.\n• Refresher training is completed at least annually, and training records are kept."},{"title":"Reporting","body":"• All incidents, near misses and unsafe conditions must be reported to a supervisor immediately and logged within 24 hours.\n• Workers can raise safety concerns with their manager, a safety representative or the HSE Manager at any time.\n• Reportable incidents are notified to the relevant Abu Dhabi Sector Regulatory Authority within the timeframes set by the OSHAD-SF incident notification mechanism."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\nOSH performance is reported to the relevant Sector Regulatory Authority as required by OSHAD-SF, and this policy is reviewed in line with any new or revised Codes of Practice.\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'OSHAD'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Health & Safety', id, '[{"title":"Purpose","body":"{{company_name}} is committed to providing safe and healthy working conditions for everyone affected by its {{industry}} activities, and to preventing work-related injury and ill health.\nThis policy follows widely recognised good practice and the laws and regulations that apply in {{location}}."},{"title":"Scope","body":"This policy applies to all {{employee_count}} employees of {{company_name}}, as well as contractors, subcontractors, visitors and anyone else working at or visiting sites under {{company_name}}''s control in {{location}}."},{"title":"Definitions","body":"• Hazard: anything with the potential to cause harm.\n• Risk: the combination of the likelihood of harm and its severity.\n• Near miss: an event that could have caused injury or damage but did not.\n• PPE: personal protective equipment, such as safety footwear, gloves, eye and hearing protection."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• HSE Manager: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"To achieve its commitment, {{company_name}} will:\n• Identify hazards and assess risks before work begins, and review assessments when work changes.\n• Apply the hierarchy of controls: eliminate, substitute, engineer, administrate, then protect with PPE.\n• Provide safe plant, equipment and systems of work, and suitable PPE at no cost to workers.\n• Give every worker the right to stop work they reasonably believe to be unsafe, without fear of reprisal.\n• Monitor workplace conditions through inspections, audits and health surveillance where required.\n• Check applicable legal requirements in {{location}} at least once a year and update this policy where needed."},{"title":"Training","body":"• All new starters complete health and safety induction before starting work.\n• Task-specific training (for example, working at height, manual handling or forklift operation) is given before workers carry out those tasks.\n• Refresher training is completed at least annually, and training records are kept."},{"title":"Reporting","body":"• All incidents, near misses and unsafe conditions must be reported to a supervisor immediately and logged within 24 hours.\n• Workers can raise safety concerns with their manager, a safety representative or the HSE Manager at any time."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\n{{company_name}} will benchmark this policy against recognised industry good practice when it is reviewed.\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'BEST_PRACTICE'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Fire Safety', id, '[{"title":"Purpose","body":"{{company_name}} will prevent fires wherever reasonably practicable and make sure that, if a fire does happen, everyone can escape safely and damage is kept to a minimum.\nThis policy is aligned with the Abu Dhabi Occupational Safety and Health System Framework (OSHAD-SF), including Element 1 (Roles, Responsibilities and Self-Regulation)."},{"title":"Scope","body":"This policy covers all premises, warehouses, vehicles and temporary sites under the control of {{company_name}} in {{location}}, and everyone on them."},{"title":"Definitions","body":"• Fire risk assessment: a structured review of fire hazards, the people at risk and the controls in place.\n• Fire warden: a trained person responsible for checking an area and helping evacuation during a fire.\n• Hot work: any work that produces flames, sparks or heat, such as welding, cutting or grinding."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• Fire Safety Coordinator: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"• Carry out and document a fire risk assessment for each premises, reviewed annually or after significant change.\n• Keep escape routes, fire exits and fire-fighting equipment clear, signed and maintained at all times.\n• Test fire alarms weekly, and service extinguishers, sprinklers and emergency lighting to the maintenance schedule.\n• Control ignition sources through a hot work permit system and safe storage of flammable materials.\n• Appoint enough trained fire wardens to cover every floor and every shift.\n• Maintain an OSH management system proportionate to {{company_name}}''s risk rating, as required by OSHAD-SF.\n• Apply the OSHAD-SF Codes of Practice that are relevant to the hazards present in {{industry}} operations.\n• Keep OSH records and documentation available for inspection by the relevant Sector Regulatory Authority.\n• Coordinate fire safety arrangements with Abu Dhabi Civil Defence requirements and keep civil defence approvals current."},{"title":"Training","body":"• All staff receive fire safety awareness training at induction and annually afterwards.\n• Fire wardens receive role-specific training and refresher training at least every two years.\n• Fire drills are held at least twice a year and the results recorded."},{"title":"Reporting","body":"• Any fire, however small, and any damaged or missing fire equipment must be reported to the Fire Safety Coordinator immediately.\n• Blocked exits and fire hazards must be reported and made safe straight away.\n• Reportable incidents are notified to the relevant Abu Dhabi Sector Regulatory Authority within the timeframes set by the OSHAD-SF incident notification mechanism."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\nOSH performance is reported to the relevant Sector Regulatory Authority as required by OSHAD-SF, and this policy is reviewed in line with any new or revised Codes of Practice.\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'OSHAD'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Fire Safety', id, '[{"title":"Purpose","body":"{{company_name}} will prevent fires wherever reasonably practicable and make sure that, if a fire does happen, everyone can escape safely and damage is kept to a minimum.\nThis policy follows widely recognised good practice and the laws and regulations that apply in {{location}}."},{"title":"Scope","body":"This policy covers all premises, warehouses, vehicles and temporary sites under the control of {{company_name}} in {{location}}, and everyone on them."},{"title":"Definitions","body":"• Fire risk assessment: a structured review of fire hazards, the people at risk and the controls in place.\n• Fire warden: a trained person responsible for checking an area and helping evacuation during a fire.\n• Hot work: any work that produces flames, sparks or heat, such as welding, cutting or grinding."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• Fire Safety Coordinator: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"• Carry out and document a fire risk assessment for each premises, reviewed annually or after significant change.\n• Keep escape routes, fire exits and fire-fighting equipment clear, signed and maintained at all times.\n• Test fire alarms weekly, and service extinguishers, sprinklers and emergency lighting to the maintenance schedule.\n• Control ignition sources through a hot work permit system and safe storage of flammable materials.\n• Appoint enough trained fire wardens to cover every floor and every shift.\n• Check applicable legal requirements in {{location}} at least once a year and update this policy where needed."},{"title":"Training","body":"• All staff receive fire safety awareness training at induction and annually afterwards.\n• Fire wardens receive role-specific training and refresher training at least every two years.\n• Fire drills are held at least twice a year and the results recorded."},{"title":"Reporting","body":"• Any fire, however small, and any damaged or missing fire equipment must be reported to the Fire Safety Coordinator immediately.\n• Blocked exits and fire hazards must be reported and made safe straight away."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\n{{company_name}} will benchmark this policy against recognised industry good practice when it is reviewed.\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'BEST_PRACTICE'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Data Protection', id, '[{"title":"Purpose","body":"{{company_name}} respects the privacy of its customers, employees and partners, and is committed to processing personal data lawfully, fairly and transparently.\nThis policy is designed to support compliance with UAE Federal Decree-Law No. 45 of 2021 on the Protection of Personal Data (PDPL) and its executive regulations as they are issued."},{"title":"Scope","body":"This policy applies to all personal data processed by {{company_name}}, in any format, and to all employees, contractors and third-party processors who handle it on {{company_name}}''s behalf."},{"title":"Definitions","body":"• Personal data: any information relating to an identified or identifiable living person.\n• Sensitive personal data: data revealing health, ethnicity, religion, biometrics, criminal records or similar.\n• Processing: anything done with personal data, including collecting, storing, using, sharing and deleting it.\n• Data subject: the person the personal data is about."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• Data Protection Officer: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"• Collect only the personal data needed for a specified, explicit and legitimate purpose.\n• Tell individuals clearly how their data will be used, through privacy notices.\n• Keep personal data accurate and up to date, and keep it no longer than the retention schedule allows.\n• Protect personal data with appropriate technical and organisational security measures.\n• Assess new systems and projects for privacy risk before they go live.\n• Process personal data only with the data subject''s consent or another basis permitted under the PDPL, and only for clear, specific purposes.\n• Honour data subject rights, including access, correction, erasure, restriction and objection, within the required timeframes.\n• Transfer personal data outside the UAE only where the PDPL permits it, such as to a country with adequate protection or under appropriate safeguards."},{"title":"Training","body":"• All staff complete data protection training at induction and annually afterwards.\n• Staff who handle sensitive personal data or customer databases receive additional role-specific training."},{"title":"Reporting","body":"• Suspected personal data breaches must be reported to the Data Protection Officer immediately.\n• Requests from individuals to exercise their data rights must be passed to the Data Protection Officer on the day they are received.\n• Personal data breaches that may affect individuals'' privacy are reported to the UAE Data Office and, where required, to the affected individuals without undue delay."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\nThis policy will be updated as the PDPL executive regulations and UAE Data Office guidance develop.\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'UAE_PDPL'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Data Protection', id, '[{"title":"Purpose","body":"{{company_name}} respects the privacy of its customers, employees and partners, and is committed to processing personal data lawfully, fairly and transparently.\nThis policy is designed to support compliance with the EU General Data Protection Regulation (Regulation (EU) 2016/679, \"GDPR\") wherever {{company_name}} processes personal data of individuals in the EU."},{"title":"Scope","body":"This policy applies to all personal data processed by {{company_name}}, in any format, and to all employees, contractors and third-party processors who handle it on {{company_name}}''s behalf."},{"title":"Definitions","body":"• Personal data: any information relating to an identified or identifiable living person.\n• Sensitive personal data: data revealing health, ethnicity, religion, biometrics, criminal records or similar.\n• Processing: anything done with personal data, including collecting, storing, using, sharing and deleting it.\n• Data subject: the person the personal data is about."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• Data Protection Officer: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"• Collect only the personal data needed for a specified, explicit and legitimate purpose.\n• Tell individuals clearly how their data will be used, through privacy notices.\n• Keep personal data accurate and up to date, and keep it no longer than the retention schedule allows.\n• Protect personal data with appropriate technical and organisational security measures.\n• Assess new systems and projects for privacy risk before they go live.\n• Apply the GDPR principles in Article 5: lawfulness, fairness and transparency; purpose limitation; data minimisation; accuracy; storage limitation; integrity and confidentiality; and accountability.\n• Keep a record of processing activities (Article 30) and carry out a Data Protection Impact Assessment for high-risk processing (Article 35).\n• Put written contracts that meet Article 28 in place with every processor."},{"title":"Training","body":"• All staff complete data protection training at induction and annually afterwards.\n• Staff who handle sensitive personal data or customer databases receive additional role-specific training."},{"title":"Reporting","body":"• Suspected personal data breaches must be reported to the Data Protection Officer immediately.\n• Requests from individuals to exercise their data rights must be passed to the Data Protection Officer on the day they are received.\n• Personal data breaches are notified to the lead supervisory authority within 72 hours of becoming aware, unless unlikely to result in a risk to individuals (Article 33), and to the individuals concerned where the risk is high (Article 34)."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\nThis policy is reviewed in light of guidance from the European Data Protection Board and relevant supervisory authorities.\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'GDPR'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Data Protection', id, '[{"title":"Purpose","body":"{{company_name}} respects the privacy of its customers, employees and partners, and is committed to processing personal data lawfully, fairly and transparently.\nThis policy follows widely recognised good practice and the laws and regulations that apply in {{location}}."},{"title":"Scope","body":"This policy applies to all personal data processed by {{company_name}}, in any format, and to all employees, contractors and third-party processors who handle it on {{company_name}}''s behalf."},{"title":"Definitions","body":"• Personal data: any information relating to an identified or identifiable living person.\n• Sensitive personal data: data revealing health, ethnicity, religion, biometrics, criminal records or similar.\n• Processing: anything done with personal data, including collecting, storing, using, sharing and deleting it.\n• Data subject: the person the personal data is about."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• Data Protection Officer: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"• Collect only the personal data needed for a specified, explicit and legitimate purpose.\n• Tell individuals clearly how their data will be used, through privacy notices.\n• Keep personal data accurate and up to date, and keep it no longer than the retention schedule allows.\n• Protect personal data with appropriate technical and organisational security measures.\n• Assess new systems and projects for privacy risk before they go live.\n• Check applicable legal requirements in {{location}} at least once a year and update this policy where needed."},{"title":"Training","body":"• All staff complete data protection training at induction and annually afterwards.\n• Staff who handle sensitive personal data or customer databases receive additional role-specific training."},{"title":"Reporting","body":"• Suspected personal data breaches must be reported to the Data Protection Officer immediately.\n• Requests from individuals to exercise their data rights must be passed to the Data Protection Officer on the day they are received."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\n{{company_name}} will benchmark this policy against recognised industry good practice when it is reviewed.\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'BEST_PRACTICE'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Information Security', id, '[{"title":"Purpose","body":"{{company_name}} will protect the confidentiality, integrity and availability of its information assets and the information entrusted to it by customers and partners.\nThis policy supports {{company_name}}''s information security management system (ISMS) in line with ISO/IEC 27001:2022, Clause 5.2 (Policy)."},{"title":"Scope","body":"This policy applies to all information systems, devices, networks, cloud services and data owned or used by {{company_name}}, and to every person who uses them."},{"title":"Definitions","body":"• Information asset: any data, system or device that has value to {{company_name}}.\n• MFA: multi-factor authentication, meaning a sign-in that needs two or more types of proof.\n• Security incident: an event that could compromise the confidentiality, integrity or availability of information."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• Information Security Manager: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"• Grant access on a least-privilege, need-to-know basis and review access rights at least quarterly.\n• Enforce multi-factor authentication for email, remote access and all privileged accounts.\n• Encrypt laptops, mobile devices and sensitive data in transit and at rest.\n• Apply critical security patches within 14 days and keep anti-malware protection active on all endpoints.\n• Back up critical data regularly and test restoration at least twice a year.\n• Classify information as Public, Internal, Confidential or Restricted and handle it accordingly.\n• Select controls through a documented information security risk assessment and record them in the Statement of Applicability (Clause 6.1.3).\n• Apply the relevant Annex A controls, including access control, cryptography, supplier security and logging and monitoring."},{"title":"Training","body":"• All users complete security awareness training at induction and annually afterwards.\n• Regular phishing simulations are run, and extra coaching is given where needed."},{"title":"Reporting","body":"• Suspected security incidents, lost devices and phishing emails must be reported to the IT service desk immediately.\n• Information security events are reported through the agreed channel and assessed to decide whether they are incidents (Annex A 5.24–5.26 and 6.8)."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\nThis policy is reviewed at planned intervals and when significant changes occur, and its effectiveness is considered in management review (Clause 9.3).\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'ISO27001'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Information Security', id, '[{"title":"Purpose","body":"{{company_name}} will protect the confidentiality, integrity and availability of its information assets and the information entrusted to it by customers and partners.\nThis policy follows widely recognised good practice and the laws and regulations that apply in {{location}}."},{"title":"Scope","body":"This policy applies to all information systems, devices, networks, cloud services and data owned or used by {{company_name}}, and to every person who uses them."},{"title":"Definitions","body":"• Information asset: any data, system or device that has value to {{company_name}}.\n• MFA: multi-factor authentication, meaning a sign-in that needs two or more types of proof.\n• Security incident: an event that could compromise the confidentiality, integrity or availability of information."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• Information Security Manager: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"• Grant access on a least-privilege, need-to-know basis and review access rights at least quarterly.\n• Enforce multi-factor authentication for email, remote access and all privileged accounts.\n• Encrypt laptops, mobile devices and sensitive data in transit and at rest.\n• Apply critical security patches within 14 days and keep anti-malware protection active on all endpoints.\n• Back up critical data regularly and test restoration at least twice a year.\n• Classify information as Public, Internal, Confidential or Restricted and handle it accordingly.\n• Check applicable legal requirements in {{location}} at least once a year and update this policy where needed."},{"title":"Training","body":"• All users complete security awareness training at induction and annually afterwards.\n• Regular phishing simulations are run, and extra coaching is given where needed."},{"title":"Reporting","body":"• Suspected security incidents, lost devices and phishing emails must be reported to the IT service desk immediately."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\n{{company_name}} will benchmark this policy against recognised industry good practice when it is reviewed.\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'BEST_PRACTICE'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Anti-Bribery', id, '[{"title":"Purpose","body":"{{company_name}} has zero tolerance for bribery and corruption in any form, and is committed to acting with integrity in all its business dealings.\nThis policy follows widely recognised good practice and the laws and regulations that apply in {{location}}."},{"title":"Scope","body":"This policy applies to all directors, employees, agents, consultants, distributors and other business partners acting for or on behalf of {{company_name}}, wherever they are located."},{"title":"Definitions","body":"• Bribe: anything of value offered, promised, given or received to improperly influence a decision.\n• Facilitation payment: a small unofficial payment to speed up a routine government action.\n• Public official: anyone who holds a legislative, administrative or judicial position, or works for a government body or state-owned company."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• Compliance Officer: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"• Never offer, give, request or accept a bribe, directly or through a third party.\n• Do not make facilitation payments, even where they may be customary locally.\n• Record all gifts and hospitality above the approved threshold in the Gifts & Hospitality Register, and get prior approval where required.\n• Carry out risk-based due diligence on agents, suppliers and partners before engaging them.\n• Keep accurate books and records that fairly reflect every transaction.\n• Check applicable legal requirements in {{location}} at least once a year and update this policy where needed."},{"title":"Training","body":"• All employees complete anti-bribery training at induction and every year afterwards.\n• Higher-risk roles, such as procurement, sales and government relations, receive enhanced training."},{"title":"Reporting","body":"• Any request for, or offer of, a bribe must be reported to the Compliance Officer immediately.\n• Concerns can be raised confidentially through the speak-up channel. Retaliation against anyone reporting in good faith is prohibited."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\n{{company_name}} will benchmark this policy against recognised industry good practice when it is reviewed.\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'BEST_PRACTICE'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Anti-Bribery', id, '[{"title":"Purpose","body":"{{company_name}} has zero tolerance for bribery and corruption in any form, and is committed to acting with integrity in all its business dealings.\nThis policy is designed to support compliance with UAE Federal Decree-Law No. 45 of 2021 on the Protection of Personal Data (PDPL) and its executive regulations as they are issued."},{"title":"Scope","body":"This policy applies to all directors, employees, agents, consultants, distributors and other business partners acting for or on behalf of {{company_name}}, wherever they are located."},{"title":"Definitions","body":"• Bribe: anything of value offered, promised, given or received to improperly influence a decision.\n• Facilitation payment: a small unofficial payment to speed up a routine government action.\n• Public official: anyone who holds a legislative, administrative or judicial position, or works for a government body or state-owned company."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• Compliance Officer: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"• Never offer, give, request or accept a bribe, directly or through a third party.\n• Do not make facilitation payments, even where they may be customary locally.\n• Record all gifts and hospitality above the approved threshold in the Gifts & Hospitality Register, and get prior approval where required.\n• Carry out risk-based due diligence on agents, suppliers and partners before engaging them.\n• Keep accurate books and records that fairly reflect every transaction.\n• Process personal data only with the data subject''s consent or another basis permitted under the PDPL, and only for clear, specific purposes.\n• Honour data subject rights, including access, correction, erasure, restriction and objection, within the required timeframes.\n• Transfer personal data outside the UAE only where the PDPL permits it, such as to a country with adequate protection or under appropriate safeguards.\n• Due diligence screening and speak-up reports involve personal data. Process it only as permitted under the PDPL, keep it confidential and retain it no longer than necessary."},{"title":"Training","body":"• All employees complete anti-bribery training at induction and every year afterwards.\n• Higher-risk roles, such as procurement, sales and government relations, receive enhanced training."},{"title":"Reporting","body":"• Any request for, or offer of, a bribe must be reported to the Compliance Officer immediately.\n• Concerns can be raised confidentially through the speak-up channel. Retaliation against anyone reporting in good faith is prohibited.\n• Personal data breaches that may affect individuals'' privacy are reported to the UAE Data Office and, where required, to the affected individuals without undue delay."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\nThis policy will be updated as the PDPL executive regulations and UAE Data Office guidance develop.\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'UAE_PDPL'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Incident Reporting', id, '[{"title":"Purpose","body":"{{company_name}} will make sure that all incidents, near misses and dangerous occurrences are reported, investigated and learned from, so that they are not repeated.\nThis policy is aligned with the Abu Dhabi Occupational Safety and Health System Framework (OSHAD-SF), including Element 1 (Roles, Responsibilities and Self-Regulation)."},{"title":"Scope","body":"This procedure applies to all employees, contractors and visitors at {{company_name}} sites in {{location}}, and to all work-related activities."},{"title":"Definitions","body":"• Incident: an unplanned event that results in injury, ill health, damage or loss.\n• Near miss: an unplanned event that did not cause harm but had the potential to.\n• Root cause: the underlying reason an incident happened.\n• Corrective action: a step taken to remove the cause of an incident and stop it happening again."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• HSE Manager: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"• Make the area safe and give first aid where needed, and call the emergency services if required.\n• Report the incident to a supervisor immediately and record it in the incident log within 24 hours.\n• Preserve evidence where it is safe to do so, and take photographs and witness statements.\n• Investigate in proportion to the actual and potential severity, using root-cause analysis.\n• Agree corrective actions with named owners and due dates, and track them to completion.\n• Share lessons learned across {{company_name}}.\n• Maintain an OSH management system proportionate to {{company_name}}''s risk rating, as required by OSHAD-SF.\n• Apply the OSHAD-SF Codes of Practice that are relevant to the hazards present in {{industry}} operations.\n• Keep OSH records and documentation available for inspection by the relevant Sector Regulatory Authority."},{"title":"Training","body":"• All staff are trained on how and when to report incidents at induction.\n• Supervisors and investigators receive training in incident investigation and root-cause analysis."},{"title":"Reporting","body":"• Monthly incident statistics, including near misses, are reported to senior management.\n• Reportable incidents are notified to the relevant Abu Dhabi Sector Regulatory Authority within the timeframes set by the OSHAD-SF incident notification mechanism."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\nOSH performance is reported to the relevant Sector Regulatory Authority as required by OSHAD-SF, and this policy is reviewed in line with any new or revised Codes of Practice.\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'OSHAD'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Incident Reporting', id, '[{"title":"Purpose","body":"{{company_name}} will make sure that all incidents, near misses and dangerous occurrences are reported, investigated and learned from, so that they are not repeated.\nThis policy forms part of {{company_name}}''s occupational health and safety (OH&S) management system and is aligned with ISO 45001:2018, Clause 5.2 (OH&S policy)."},{"title":"Scope","body":"This procedure applies to all employees, contractors and visitors at {{company_name}} sites in {{location}}, and to all work-related activities."},{"title":"Definitions","body":"• Incident: an unplanned event that results in injury, ill health, damage or loss.\n• Near miss: an unplanned event that did not cause harm but had the potential to.\n• Root cause: the underlying reason an incident happened.\n• Corrective action: a step taken to remove the cause of an incident and stop it happening again."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• HSE Manager: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"• Make the area safe and give first aid where needed, and call the emergency services if required.\n• Report the incident to a supervisor immediately and record it in the incident log within 24 hours.\n• Preserve evidence where it is safe to do so, and take photographs and witness statements.\n• Investigate in proportion to the actual and potential severity, using root-cause analysis.\n• Agree corrective actions with named owners and due dates, and track them to completion.\n• Share lessons learned across {{company_name}}.\n• Consult and involve non-managerial workers in hazard identification, risk assessment and decisions on controls (ISO 45001 Clause 5.4).\n• Identify legal and other requirements that apply and evaluate compliance with them at planned intervals (Clauses 6.1.3 and 9.1.2).\n• Set measurable OH&S objectives and plan how they will be achieved (Clause 6.2).\n• Involve workers in investigating incidents and in deciding corrective actions."},{"title":"Training","body":"• All staff are trained on how and when to report incidents at induction.\n• Supervisors and investigators receive training in incident investigation and root-cause analysis."},{"title":"Reporting","body":"• Monthly incident statistics, including near misses, are reported to senior management.\n• Incidents and nonconformities are investigated, root causes identified and corrective actions tracked to closure (Clause 10.2)."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\nPerformance against this policy is considered in management review (Clause 9.3) and used to drive continual improvement (Clause 10.3).\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'ISO45001'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Emergency Evacuation', id, '[{"title":"Purpose","body":"{{company_name}} will make sure that everyone on its premises can be evacuated quickly and safely in an emergency.\nThis policy is aligned with the Abu Dhabi Occupational Safety and Health System Framework (OSHAD-SF), including Element 1 (Roles, Responsibilities and Self-Regulation)."},{"title":"Scope","body":"This plan applies to all buildings and sites operated by {{company_name}} in {{location}}, and to everyone present, including visitors, contractors and people with disabilities."},{"title":"Definitions","body":"• Assembly point: the designated safe location where people gather after evacuating.\n• Incident Controller: the person in charge of the evacuation until the emergency services arrive.\n• PEEP: a Personal Emergency Evacuation Plan for someone who may need help to evacuate."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• Emergency Response Coordinator: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"• Display evacuation routes and assembly point maps prominently on every floor.\n• On hearing the alarm, stop work, leave by the nearest safe exit and go directly to the assembly point. Do not use lifts.\n• Fire wardens sweep their zones and report to the Incident Controller at the assembly point.\n• Account for all staff and visitors using sign-in records.\n• Re-enter buildings only when the emergency services or Incident Controller give the all-clear.\n• Prepare a PEEP for every person who needs help to evacuate.\n• Maintain an OSH management system proportionate to {{company_name}}''s risk rating, as required by OSHAD-SF.\n• Apply the OSHAD-SF Codes of Practice that are relevant to the hazards present in {{industry}} operations.\n• Keep OSH records and documentation available for inspection by the relevant Sector Regulatory Authority."},{"title":"Training","body":"• All staff and regular contractors are briefed on evacuation procedures at induction.\n• Evacuation drills are held at least twice a year, timed and reviewed for improvements."},{"title":"Reporting","body":"• Problems found during drills, such as blocked routes or alarms that cannot be heard, are reported and fixed promptly.\n• Reportable incidents are notified to the relevant Abu Dhabi Sector Regulatory Authority within the timeframes set by the OSHAD-SF incident notification mechanism."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\nOSH performance is reported to the relevant Sector Regulatory Authority as required by OSHAD-SF, and this policy is reviewed in line with any new or revised Codes of Practice.\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'OSHAD'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Emergency Evacuation', id, '[{"title":"Purpose","body":"{{company_name}} will make sure that everyone on its premises can be evacuated quickly and safely in an emergency.\nThis policy follows widely recognised good practice and the laws and regulations that apply in {{location}}."},{"title":"Scope","body":"This plan applies to all buildings and sites operated by {{company_name}} in {{location}}, and to everyone present, including visitors, contractors and people with disabilities."},{"title":"Definitions","body":"• Assembly point: the designated safe location where people gather after evacuating.\n• Incident Controller: the person in charge of the evacuation until the emergency services arrive.\n• PEEP: a Personal Emergency Evacuation Plan for someone who may need help to evacuate."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• Emergency Response Coordinator: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"• Display evacuation routes and assembly point maps prominently on every floor.\n• On hearing the alarm, stop work, leave by the nearest safe exit and go directly to the assembly point. Do not use lifts.\n• Fire wardens sweep their zones and report to the Incident Controller at the assembly point.\n• Account for all staff and visitors using sign-in records.\n• Re-enter buildings only when the emergency services or Incident Controller give the all-clear.\n• Prepare a PEEP for every person who needs help to evacuate.\n• Check applicable legal requirements in {{location}} at least once a year and update this policy where needed."},{"title":"Training","body":"• All staff and regular contractors are briefed on evacuation procedures at induction.\n• Evacuation drills are held at least twice a year, timed and reviewed for improvements."},{"title":"Reporting","body":"• Problems found during drills, such as blocked routes or alarms that cannot be heard, are reported and fixed promptly."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\n{{company_name}} will benchmark this policy against recognised industry good practice when it is reviewed.\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'BEST_PRACTICE'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Code of Conduct', id, '[{"title":"Purpose","body":"This Code sets out the standards of behaviour {{company_name}} expects from everyone who works for it, and reflects its values of integrity, respect and accountability.\nThis policy follows widely recognised good practice and the laws and regulations that apply in {{location}}."},{"title":"Scope","body":"This Code applies to all employees, directors, temporary staff and contractors of {{company_name}}, wherever they work."},{"title":"Definitions","body":"• Conflict of interest: a situation where personal interests could influence, or appear to influence, business decisions.\n• Harassment: unwanted conduct that violates a person''s dignity or creates an intimidating or hostile environment.\n• Confidential information: non-public information about {{company_name}}, its customers or partners."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• HR Manager: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"• Treat colleagues, customers and partners with dignity and respect. Harassment, bullying and discrimination are never acceptable.\n• Avoid conflicts of interest and declare any that arise to your manager.\n• Protect company assets, confidential information and intellectual property.\n• Comply with all applicable laws and regulations in {{location}} and every country where {{company_name}} operates.\n• Use company systems and social media responsibly.\n• Check applicable legal requirements in {{location}} at least once a year and update this policy where needed."},{"title":"Training","body":"• All staff read and acknowledge this Code at induction and complete a refresher every year."},{"title":"Reporting","body":"• Concerns about breaches of this Code can be raised with a line manager, HR, or confidentially through the speak-up channel.\n• {{company_name}} will not tolerate retaliation against anyone who raises a concern in good faith."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\n{{company_name}} will benchmark this policy against recognised industry good practice when it is reviewed.\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'BEST_PRACTICE'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
INSERT INTO policy_templates (policy_type, framework_id, sections)
  SELECT 'Code of Conduct', id, '[{"title":"Purpose","body":"This Code sets out the standards of behaviour {{company_name}} expects from everyone who works for it, and reflects its values of integrity, respect and accountability.\nThis policy forms part of {{company_name}}''s occupational health and safety (OH&S) management system and is aligned with ISO 45001:2018, Clause 5.2 (OH&S policy)."},{"title":"Scope","body":"This Code applies to all employees, directors, temporary staff and contractors of {{company_name}}, wherever they work."},{"title":"Definitions","body":"• Conflict of interest: a situation where personal interests could influence, or appear to influence, business decisions.\n• Harassment: unwanted conduct that violates a person''s dignity or creates an intimidating or hostile environment.\n• Confidential information: non-public information about {{company_name}}, its customers or partners."},{"title":"Roles & Responsibilities","body":"• Senior Management: approve this policy, provide the resources needed to implement it and lead by example.\n• HR Manager: own and maintain this policy, monitor compliance and report performance to senior management.\n• Line Managers: make sure their teams understand and follow this policy, and act promptly on concerns raised.\n• All Employees and Contractors: follow this policy, complete required training and report concerns without delay."},{"title":"Procedure","body":"• Treat colleagues, customers and partners with dignity and respect. Harassment, bullying and discrimination are never acceptable.\n• Avoid conflicts of interest and declare any that arise to your manager.\n• Protect company assets, confidential information and intellectual property.\n• Comply with all applicable laws and regulations in {{location}} and every country where {{company_name}} operates.\n• Use company systems and social media responsibly.\n• Consult and involve non-managerial workers in hazard identification, risk assessment and decisions on controls (ISO 45001 Clause 5.4).\n• Identify legal and other requirements that apply and evaluate compliance with them at planned intervals (Clauses 6.1.3 and 9.1.2).\n• Set measurable OH&S objectives and plan how they will be achieved (Clause 6.2).\n• Follow all safety rules, wear required PPE and never work under the influence of alcohol or drugs.\n• Take part in consultation on health and safety matters and use your right to stop unsafe work."},{"title":"Training","body":"• All staff read and acknowledge this Code at induction and complete a refresher every year."},{"title":"Reporting","body":"• Concerns about breaches of this Code can be raised with a line manager, HR, or confidentially through the speak-up channel.\n• {{company_name}} will not tolerate retaliation against anyone who raises a concern in good faith.\n• Incidents and nonconformities are investigated, root causes identified and corrective actions tracked to closure (Clause 10.2)."},{"title":"Review & Approval","body":"This policy is effective from {{effective_date}} and will be reviewed by {{review_date}}, or sooner after a significant incident, a change in law or regulation, an audit finding or a material change to {{company_name}}''s operations.\nPerformance against this policy is considered in management review (Clause 9.3) and used to drive continual improvement (Clause 10.3).\nApproved by the senior management of {{company_name}}."}]'::jsonb FROM frameworks WHERE code = 'ISO45001'
  ON CONFLICT (policy_type, framework_id) DO UPDATE SET sections = EXCLUDED.sections;
